#!/usr/bin/env ruby
require'json';require'fileutils';root=File.expand_path('..',__dir__);docs=File.expand_path('../Client/docs',root);index=File.read(File.join(docs,'README.md'));current=Dir.glob(File.join(docs,'*.md')).reject{|p|File.basename(p)=='README.md'};refs=current.flat_map{|p|File.readlines(p).each_with_index.select{|l,_|l.match?(/(?:docs\/)?Archive\//)}.map{|l,n|{file:p.delete_prefix(docs+'/'),line:n+1,text:l.strip}}};checks={priorityDeclared:index.include?('当前权威文档优先级'),archiveNonAuthoritative:index.include?('禁止作为当前实现、构建、测试或发布依据'),noCurrentArchiveDependencies:refs.empty?};report={schemaVersion:1,currentDocuments:current.map{|p|File.basename(p)},archiveDocuments:Dir.glob(File.join(docs,'Archive/**/*.md')).length,referencesFromCurrent:refs,checks:checks};out=File.join(root,'docs/generated/carch07-doc-archive.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort("CARCH07 failed: #{checks}")unless checks.values.all?;puts 'CARCH07 PASS: current documentation priority and archive drift gate established'
